async (page) => {
  const input = page.locator('.new-todo');
  const snap = async () => await page.evaluate(() => ({
    titles: [...document.querySelectorAll('[data-testid="todo-title"]')].map(e => e.textContent),
    count: document.querySelector('[data-testid="todo-count"]')?.textContent,
    inputValue: document.querySelector('.new-todo')?.value,
  }));
  const out = {};
  // whitespace-only submit
  await input.fill('   ');
  await input.press('Enter');
  out.afterWhitespaceOnly = await snap();
  // empty submit
  await input.fill('');
  await input.press('Enter');
  out.afterEmpty = await snap();
  // leading/trailing whitespace
  await input.fill('   padded todo   ');
  await input.press('Enter');
  out.afterPadded = await snap();
  // duplicate
  await input.fill('buy milk');
  await input.press('Enter');
  out.afterDuplicate = await snap();
  // special chars
  await input.fill('<b>bold</b> & "quotes" éü');
  await input.press('Enter');
  out.afterSpecial = await snap();
  out.specialHtml = await page.evaluate(() => document.querySelectorAll('[data-testid="todo-title"]')[3]?.innerHTML);
  return out;
}

