async (page) => {
  const items = page.getByTestId('todo-item');
  const out = {};
  const titles = async () => await page.evaluate(() => [...document.querySelectorAll('[data-testid="todo-title"]')].map(e => e.textContent));

  // double click first item
  await items.nth(0).dblclick();
  out.classAfterDblclick = await items.nth(0).getAttribute('class');
  out.editFocused = await page.evaluate(() => document.activeElement?.className);
  out.editValue = await items.nth(0).locator('.edit').inputValue();
  out.htmlWhileEditing = await items.nth(0).innerHTML;

  // Escape cancels
  const edit = items.nth(0).locator('.edit');
  await edit.fill('changed via escape');
  await edit.press('Escape');
  out.afterEscape = { titles: await titles(), cls: await items.nth(0).getAttribute('class') };

  // Enter saves with trimming
  await items.nth(0).dblclick();
  await items.nth(0).locator('.edit').fill('   edited milk   ');
  await items.nth(0).locator('.edit').press('Enter');
  out.afterEnter = await titles();

  // Blur behavior
  await items.nth(1).dblclick();
  await items.nth(1).locator('.edit').fill('blurred edit');
  await page.locator('.new-todo').click();
  out.afterBlur = { titles: await titles(), cls: await items.nth(1).getAttribute('class') };

  // Empty edit + Enter
  await items.nth(1).dblclick();
  await items.nth(1).locator('.edit').fill('');
  await items.nth(1).locator('.edit').press('Enter');
  out.afterEmptyEdit = await titles();

  // Whitespace-only edit + Enter
  await items.nth(1).dblclick();
  await items.nth(1).locator('.edit').fill('    ');
  await items.nth(1).locator('.edit').press('Enter');
  out.afterWhitespaceEdit = await titles();

  return out;
}

