async (page) => {
  const out = {};
  await page.evaluate(() => localStorage.clear());
  await page.goto('https://demo.playwright.dev/todomvc/');
  const input = page.locator('.new-todo');
  for (const t of ['one', 'two', 'three']) { await input.fill(t); await input.press('Enter'); }
  const state = async () => await page.evaluate(() => ({
    items: [...document.querySelectorAll('[data-testid="todo-item"]')].map(e => ({ t: e.querySelector('[data-testid="todo-title"]').textContent, cls: e.className, checked: e.querySelector('.toggle').checked })),
    count: document.querySelector('[data-testid="todo-count"]')?.textContent,
    clearBtn: (() => { const b = document.querySelector('.clear-completed'); return b ? { text: b.textContent, visible: !!b.offsetParent } : null; })(),
    toggleAll: (() => { const t = document.querySelector('#toggle-all'); return t ? t.checked : null; })(),
    url: location.hash,
    mainVisible: !!document.querySelector('.main'),
    footerVisible: !!document.querySelector('.footer'),
  }));
  out.initial = await state();
  // toggle second item
  await page.getByTestId('todo-item').nth(1).locator('.toggle').check();
  out.afterToggleOne = await state();
  // toggle all
  await page.locator('#toggle-all').check();
  out.afterToggleAll = await state();
  // uncheck toggle-all
  await page.locator('#toggle-all').uncheck();
  out.afterUntoggleAll = await state();
  return out;
}

