  // destroy button CSS visibility
  out.destroyStyles = await page.evaluate(() => {
    const b = document.querySelector('.destroy');
    const cs = getComputedStyle(b);
    return { display: cs.display, opacity: cs.opacity, visibility: cs.visibility };
