  out.emptyState = await page.evaluate(() => ({
    hasMain: !!document.querySelector('.main'), hasFooter: !!document.querySelector('.footer'),
    stored: localStorage.getItem('react-todos'),
    inputPlaceholder: document.querySelector('.new-todo')?.placeholder,
    inputFocused: document.activeElement?.className,
    title: document.title,
